/// <summary>
/// This is a service class
/// CB355_DutyRoll(ExciseRegister)
/// </summary>
class METDutyRollMonthlyService extends METSysOperationService
{
    List                itemList;
    List                siteList;
    boolean             adHoc;
    boolean             runForExcise;
    private guid        topPickingProcessId;

}

Method.Source:
/// <summary>
/// Returns name of the task service class.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METDutyRollMonthlyTaskService);
}

/// <summary>
/// Returns name of the task service class method.
/// </summary>
/// <returns>Task service class method name</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METDutyRollMonthlyTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:MonthlyDutyRoll";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METDutyRollMonthlyContract</c>
/// </param>
public void process(METDutyRollMonthlyContract _contract)
{
    this.processInternal(_contract);
}

    /// <summary>
    /// Initialise global variables.
    /// </summary>
    public void initialise()
    {
        super();

        this.stageDataIntoQueue();
    }

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METDutyRollMonthlyContract contract = _taskDataContract as METDutyRollMonthlyContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METDutyRollMonthlyContract();
}

    /// <summary>
    /// Stages data int table <c>METDutyRollMonthlyQueue</c>.
    /// </summary>
    void stageDataIntoQueue()
    {
        #OCCRetryCount

        InventSite                  inventSite;
        InventSiteId                siteId;
        METDutyRollMonthlyContract  contract;

        topPickingProcessId = newGuid();
        contract = dataContract as METDutyRollMonthlyContract;

        try
        {            
            itemList = contract.parmItemList();
            siteList = contract.parmSiteList();
            adHoc = contract.parmAdHoc();
            runForExcise = contract.parmRunForExcise();

            METDutyRollMonthlyQueue::cleanUpABNValidationJobQueue();

            if (!siteList.empty())
            {
                ListEnumerator iter = siteList.getEnumerator();

                while (iter.moveNext())
                {
                    siteId = iter.current();
                    this.stageDataIntoQueueQueryFiltered(siteId);
                }
            }
            else
            {
                while select inventSite
                    where inventSite.METBondedWarehouse == NoYes::Yes
                    {
                        this.stageDataIntoQueueQueryFiltered(inventSite.SiteId);
                    }
            }          
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            curext();
        }
    }

    /// <summary>
    /// Stages <c>Query</c> filtered data into <c>METDutyRollMonthlyQueue</c>.
    /// </summary>
    /// <param name = "_query"> <c>Query</c>. </param>
    /// <param name = "_month"> months. </param>
    void stageDataIntoQueueQueryFiltered(InventSiteId _siteId)
    {
        const str tariffCodeC = "@MET:TariffCodeC";
        const str tariffCodeE = "@MET:TariffCodeE";
        QueryRun                queryRunItem;
        Query                   query;
        QueryBuildDataSource    metTariffItemCodeQbds;
        QueryBuildRange         qbr;
        InventTable             inventTable;
        ItemId                  itemId;
        METDutyRollMonthlyQueue dutyRollMonthlyQueue;
        RecordInsertList        queueInsertList;

        ttsbegin;
        if (!itemList.empty())
        {
            queueInsertList = new RecordInsertList(tableNum(METDutyRollMonthlyQueue));
            ListEnumerator itemIter = itemList.getEnumerator();

            while (itemIter.moveNext())
            {
                itemId = itemIter.current();

                dutyRollMonthlyQueue.clear();
                dutyRollMonthlyQueue.ProcessId = topPickingProcessId;
                dutyRollMonthlyQueue.ItemId = itemId;
                dutyRollMonthlyQueue.SiteId = _siteId;
                queueInsertList.add(dutyRollMonthlyQueue);
            }

            // Bulk insert all records at once
            queueInsertList.insertDatabase();
        }
        else
        {
            query = new Query(queryStr(METInventTableTariffItemCode));
            if (!adHoc && !runForExcise)
            {
                metTariffItemCodeQbds = query.dataSourceTable(tableNum(METTariffItemCodeBase));
                qbr = metTariffItemCodeQbds.addRange(fieldNum(METTariffItemCodeBase, CustomsExcise));
                qbr.value(queryValue(tariffCodeC));
            }
            else if (runForExcise)
            {
                metTariffItemCodeQbds = query.dataSourceTable(tableNum(METTariffItemCodeBase));
                qbr = metTariffItemCodeQbds.addRange(fieldNum(METTariffItemCodeBase, CustomsExcise));
                qbr.value(queryValue(tariffCodeE));
            }

            Map fieldMapping = new Map(Types::String, Types::Container);
            fieldMapping.insert(fieldStr(METDutyRollMonthlyQueue, ProcessId), [metTariffItemCodeQbds.uniqueId(), topPickingProcessId]);
            fieldMapping.insert(fieldStr(METDutyRollMonthlyQueue, ItemId), [metTariffItemCodeQbds.uniqueId(), fieldStr(inventTable, ItemId)]);
            fieldMapping.insert(fieldStr(METDutyRollMonthlyQueue, SiteId), [metTariffItemCodeQbds.uniqueId(), _siteId]);

            // 4. Execute the insert_recordset            
            Query::insert_recordset(dutyRollMonthlyQueue, fieldMapping, query);            
        }
        ttscommit;
    }
